  SELECT 'Suzuki Alto K10', (SELECT id FROM tblbrands WHERE BrandName = 'Maruti' LIMIT 1), 'A small, light city car that is easy to park in Kathmandu''s narrow streets and cheap to run. Best for one or two people and short trips.', 4000, 'Petrol', 2022, 5, 'Hatchback', 0, 'placeholder-vehicle.jpg', 'placeholder-vehicle.jpg', 'placeholder-vehicle.jpg', 'placeholder-vehicle.jpg', '', 1, 1, 1, 1, 1, 1, 1, 1, NULL, 1, NULL, NULL
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tblvehicles WHERE VehiclesTitle = 'Suzuki Alto K10');
